import math

def nq_func(phi_deg):
    phi = math.radians(phi_deg)
    return math.exp(math.pi * math.tan(phi)) * (math.tan(math.radians(45 + phi_deg / 2)))**2

def nc_func(phi_deg):
    if phi_deg == 0:
        return 5.14
    return (nq_func(phi_deg) - 1.0) / math.tan(math.radians(phi_deg))

